"""Build the v2 report; validation-gated summaries, no new model fitting."""
import json,hashlib
import numpy as np,pandas as pd,joblib
from sklearn.metrics import log_loss
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))  # shared core modules sit at the top level
from pipeline import ROOT
from v2_model import OUT,probabilities

def ece(y,p):
    conf=p.max(axis=1);correct=p.argmax(axis=1)==y;value=0
    for j in range(10):
        m=(conf>=j/10)&(conf<(j+1)/10 if j<9 else conf<=1)
        if m.any():value+=m.mean()*abs(conf[m].mean()-correct[m].mean())
    return float(value)

f=joblib.load(OUT/'frozen_model.joblib');spec=json.loads((ROOT/'protocol.json').read_text());cal=[]
for r in spec['records']:
    if r['split']!='test' or not r['confirmatory_night']:continue
    z=np.load(ROOT/'data/features'/f"{r['subject']}.npz");mask=(z['y']<5)&z['good']
    for t,label in [(1,'before_temperature'),(f['temperature'],'after_temperature')]:
        p=probabilities(f['model'],z['X'],z['good'],f['transition'],f['prior'],f['weight'],t,z['onset'])[mask];y=z['y'][mask]
        cal.append({'subject':r['subject'],'variant':label,'log_loss':float(log_loss(y,p,labels=list(range(5)))),'brier':float(np.mean(np.sum((p-np.eye(5)[y])**2,axis=1))),'ece':ece(y,p)})
pd.DataFrame(cal).to_csv(OUT/'probability_calibration.csv',index=False)
cal_summary=pd.DataFrame(cal).groupby('variant')[['log_loss','brier','ece']].mean().to_dict('index')
(OUT/'probability_calibration_summary.json').write_text(json.dumps(cal_summary,indent=2))
hist=json.loads((OUT/'historical_boas_metrics.json').read_text());ext=json.loads((OUT/'external_metrics.json').read_text());v1=json.loads((ROOT/'results/metrics.json').read_text());freeze=json.loads((OUT/'freeze_record.json').read_text())
gate={'interval_release_enabled':False,'reason':'Observed 90%-target interval coverage was 60% on historical BOAS and 20%/25% on the new full-window external test. Calibrated-range claims are withheld.','point_summary_status':'experimental estimate; not a clinical quantity','external_validation_scope':'Independent cohort/device/scoring shift. Not in-domain headband confirmation or ADHD/medication validation.','historical_status':'Development comparison on previously inspected people, never relabelled as new independent evidence.'}
(OUT/'release_gate.json').write_text(json.dumps(gate,indent=2))
data={'historical':hist,'external':ext,'v1':v1,'gate':gate,'freeze':freeze,'probability_calibration':cal_summary,'cohorts':{}}
for cohort,prefix in [('BOAS development','historical_boas'),('Sleep-EDF external','external')]:
    data['cohorts'][cohort]={'predictions':json.loads((OUT/(prefix+'_predictions.json')).read_text()),'people':pd.read_csv(OUT/(prefix+'_people.csv')).to_dict('records')}
old_predictions=json.loads((ROOT/'results/predictions.json').read_text())
for subject,record in data['cohorts']['BOAS development']['predictions'].items():
    record['vendor']=old_predictions[subject]['bitbrain']
    record['v1']=old_predictions[subject]['model']
payload=json.dumps(data,allow_nan=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Goldilocks v2 | Validation explorer</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f5f6;color:#16283a;font:16px system-ui}header{background:#16283a;color:white;padding:32px 5vw}main{max-width:1150px;margin:auto;padding:24px}h1{margin:6px 0}h2{font-size:22px}.badge{display:inline-block;background:#dce8ed;color:#163f52;padding:6px 9px;border-radius:4px;font-size:12px;font-weight:700}section,.card{background:white;border:1px solid #dce3e8;border-radius:9px;padding:22px;margin-bottom:20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.big{font-size:30px;font-weight:700}small{color:#526578}.warning{padding:15px;background:#fff4e8;border-left:5px solid #b66f2f}select,button{font:inherit;padding:9px;border:1px solid #8594a3;border-radius:4px;background:white}button{background:#204d62;color:white;cursor:pointer}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:10px;text-align:left;border-bottom:1px solid #dce3e8}.overflow{overflow-x:auto}.plot svg{min-width:820px;width:100%;height:auto}a{color:#155a7f}@media(max-width:700px){.cards{grid-template-columns:1fr}main{padding:12px}}</style>
<header><span class="badge">FROZEN MODEL · PUBLIC ADULT EEG · RETROSPECTIVE</span><h1>Goldilocks AI · v2</h1><p>Better stage decoding. Independent transfer testing. Claims bounded by measured reliability.</p></header><main>
<div class="cards"><div class="card"><small>BOAS development kappa, v1 → v2</small><div class="big">0.584 → 0.661</div></div><div class="card"><small>New external cohort</small><div class="big">20 people</div><small>Sleep-EDF, different montage and scoring</small></div><div class="card"><small>Calibrated summary-range release</small><div class="big">Withheld</div><small>The measured coverage target was not met</small></div></div>
<section><h2>What improved, and what did not</h2><p>Temporal, channel-shared EEG features and training-derived sequence smoothing improved stage kappa and macro-F1 on the original BOAS test people. Because v1 results had already been inspected, this is a development comparison. The released Bitbrain comparator still leads.</p><div class="overflow"><table><thead><tr><th>Evaluation</th><th>People</th><th>Kappa</th><th>Sleep-time MAE</th><th>Global / scaled range coverage</th></tr></thead><tbody id="metrics"></tbody></table></div><p>The primary external result uses every valid scored epoch in the complete recording. Its long daytime wake periods differ from the BOAS night window. The prespecified secondary sleep-window result is shown as secondary, not substituted for the primary failure.</p><div class="warning">Stage accuracy does not establish reliable sleep totals. V2 missed the 90% interval-coverage target. Per-person numerical prediction ranges remain research diagnostics in the data files; the interface does not release them as calibrated ranges.</div></section>
<section><h2>Inspect frozen predictions</h2><label>Cohort <select id="cohort"></select></label> <label>Recording <select id="record"></select></label> <label><input id="reveal" type="checkbox"> Reveal reference</label><p id="scope"></p><div id="plot" class="plot overflow"></div><p id="point"></p><small>BOAS reference reveal also displays Bitbrain and v1 on the same time axis. YASA was not run; no curve is invented. On a small screen, scroll the plot horizontally. Unknown reference and unusable signals are gaps. Probabilities remain model estimates, not clinical safety scores.</small></section>
<section><h2>Challenge a claim</h2><button id="range">Request a calibrated sleep-time range</button><p id="reason"></p><button id="latency">Request clinical lights-off latency</button><p id="latencyResult"></p><button id="export">Export selected evidence</button></section>
<section><h2>Evaluation discipline</h2><ul><li>48 fit people; six model-selection people; six separate probability-calibration people; 20 summary-calibration people. Repeat nights remain grouped.</li><li>Three sequence weights were compared only on six development people. No old test, summary-calibration or external labels selected the model.</li><li>Model, temperature, interval rules and cohort were frozen before opening external reference labels. Model checksum is recorded.</li><li>All 20 external signal/reference pairs match PhysioNet's published SHA-256 values. Fpz-Cz alone is resampled from 100 to 256 Hz using a fixed preprocessing rule.</li><li>R&amp;K stages 3 and 4 map to N3. This reference differs from BOAS consensus scoring, so external results do not confirm identical-device performance.</li><li>Centered context uses neighbouring future epochs: this is offline retrospective inference.</li></ul><p id="probability"></p><p>No ADHD diagnosis, medication-response prediction, personalised gel choice, safe-dose recommendation or clinical validation is claimed.</p><p><a href="https://physionet.org/content/sleep-edfx/1.0.0/">Independent data and attribution</a> · <a href="https://openneuro.org/datasets/ds005555">BOAS source</a></p></section></main>
<script>const DATA=__PAYLOAD__,names=['Wake','N1','N2','N3','REM'];const $=id=>document.getElementById(id);let all=[['BOAS v1 · historical',DATA.v1.test_people,DATA.v1.methods.feature_model.kappa,DATA.v1.model_tst_mae_minutes,DATA.v1.observed_summary_coverage,null],['BOAS v2 · development',20,DATA.historical.results.kappa,DATA.historical.results.tst_error_minutes,DATA.historical.results.global_covered,DATA.historical.results.normalized_covered],['External · complete scored recording',20,DATA.external.results.kappa,DATA.external.results.tst_error_minutes,DATA.external.results.global_covered,DATA.external.results.normalized_covered],['External · secondary sleep window',20,DATA.external.secondary_reference_defined_sleep_window.kappa,DATA.external.secondary_reference_defined_sleep_window.tst_error_minutes,DATA.external.secondary_reference_defined_sleep_window.global_covered,DATA.external.secondary_reference_defined_sleep_window.normalized_covered]];$('metrics').innerHTML=all.map(r=>'<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td>'+r[2].toFixed(3)+'</td><td>'+r[3].toFixed(1)+' min</td><td>'+(100*r[4]).toFixed(0)+'% / '+(r[5]===null?'not tested':(100*r[5]).toFixed(0)+'%')+'</td></tr>').join('');
Object.keys(DATA.cohorts).forEach(k=>{let o=document.createElement('option');o.value=k;o.textContent=k;$('cohort').append(o)});function setRecords(){let c=DATA.cohorts[$('cohort').value];$('record').innerHTML='';Object.keys(c.predictions).forEach(k=>{let o=document.createElement('option');o.value=k;o.textContent=k;$('record').append(o)});draw()};
function selected(){let c=DATA.cohorts[$('cohort').value],id=$('record').value;return {z:c.predictions[id],r:c.people.find(p=>p.subject===id),id}};
function draw(){let {z,r,id}=selected(),keys=$('reveal').checked?(z.vendor?['reference','vendor','v1','model']:['reference','model']):['model'],H=keys.length*140+35;let svg='<svg viewBox="0 0 1060 '+H+'" role="img" aria-label="Aligned sleep-stage predictions">';keys.forEach((key,j)=>{let top=25+j*140;svg+='<text x="4" y="'+(top-9)+'" font-size="14">'+({reference:'Expert reference',vendor:'Released Bitbrain',v1:'Frozen v1 model',model:'Frozen v2 model'}[key])+'</text>';names.forEach((n,i)=>svg+='<text x="4" y="'+(top+23*i+4)+'" font-size="12">'+n+'</text><line x1="80" y1="'+(top+23*i)+'" x2="1040" y2="'+(top+23*i)+'" stroke="#dfe6ea"/>');let d='';z[key].forEach((v,i)=>{if(v<0||v>4||((key==='model'||key==='v1')&&!z.good[i]))return;let x=80+z.onset[i]/z.onset.at(-1)*960,xe=80+Math.min(z.onset[i]+30,z.onset.at(-1))/z.onset.at(-1)*960,y=top+v*23;d+='M'+x.toFixed(2)+' '+y+'H'+xe.toFixed(2)});svg+='<path d="'+d+'" fill="none" stroke="'+(key==='model'?'#af6c28':'#18364a')+'" stroke-width="1.5"/>'});let hours=z.onset.at(-1)/3600;for(let h=0;h<=hours;h+=hours>12?2:1)svg+='<text x="'+(80+h/hours*960)+'" y="'+(H-5)+'" font-size="12">'+h+' h</text>';$('plot').innerHTML=svg+'</svg>';$('scope').textContent=$('cohort').value.startsWith('BOAS')?DATA.gate.historical_status:DATA.gate.external_validation_scope;$('point').textContent=id+' | experimental model sleep total '+r.model_tst_minutes.toFixed(1)+' min | reference '+($('reveal').checked?r.reference_tst_minutes.toFixed(1)+' min':'hidden')+' | calibrated range unavailable. Primary recording window; not clinical lights-off sleep time.';}
$('cohort').onchange=setRecords;$('record').onchange=draw;$('reveal').onchange=draw;setRecords();$('range').onclick=()=>{$('reason').textContent=DATA.gate.reason};$('latency').onclick=()=>{$('latencyResult').textContent='Unavailable: clinical lights-off markers are not part of the validated inference contract. Recording origin and reference-defined evaluation windows are different quantities.'};$('export').onclick=()=>{let {r,id}=selected();let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({cohort:$('cohort').value,subject:id,experimental_sleep_total:r.model_tst_minutes,calibrated_interval:null,release_gate:DATA.gate,model_sha256:DATA.freeze.model_sha256},null,2)],{type:'application/json'}));a.download=id+'_v2_evidence.json';a.click();URL.revokeObjectURL(a.href)};let ps=DATA.probability_calibration;$('probability').textContent='Historical BOAS probability diagnostics: log loss before/after temperature '+ps.before_temperature.log_loss.toFixed(3)+' / '+ps.after_temperature.log_loss.toFixed(3)+', confidence ECE '+ps.before_temperature.ece.toFixed(3)+' / '+ps.after_temperature.ece.toFixed(3)+'. These are empirical diagnostics, not a guarantee.';</script></html>'''
